'use strict';
if \(!globalThis.DOMMatrix\) globalThis.DOMMatrix = require\('@napi-rs/canvas'\).DOMMatrix;
const fs = require\('fs'\);
const path = require\('path'\);
const { pathToFileURL } = require\('url'\);
const PDF_PATH = path.join\(__dirname, 'caci-2026.pdf'\);

function extractPageText\(textContent\) {
  const items = textContent.items.filter\(item => item.str.trim\(\)\);
  if \(items.length === 0\) return '';
  const lineMap = new Map\(\);
  for \(const item of items\) {
    const y = Math.round\(item.transform[5]\);
    if \(!lineMap.has\(y\)\) lineMap.set\(y, []\);
    lineMap.get\(y\).push\(item\);
  }
  const sortedYs = Array.from\(lineMap.keys\(\)\).sort\(\(a, b\) => b - a\);
  const lines = [];
  let prevY = null;
  for \(const y of sortedYs\) {
    if \(prevY !== null && \(prevY - y\) > 20\) lines.push\(''\);
    const lineItems = lineMap.get\(y\).sort\(\(a, b\) => a.transform[4] - b.transform[4]\);
    lines.push\(lineItems.map\(item => item.str\).join\(' '\).trim\(\)\);
    prevY = y;
  }
  return lines.join\('\\n'\);
}

async function main\(\) {
  const dataBuffer = fs.readFileSync\(PDF_PATH\);
  const pdfjsLib = await import\('pdfjs-dist/legacy/build/pdf.mjs'\);
  const workerPath = require.resolve\('pdfjs-dist/legacy/build/pdf.worker.mjs'\);
  pdfjsLib.GlobalWorkerOptions.workerSrc = pathToFileURL\(workerPath\).href;
  const pdf = await pdfjsLib.getDocument\({ data: new Uint8Array\(dataBuffer\) }\).promise;

  // Find page for instruction 216
  for \(let i = 240; i <= 280; i++\) {
    const page = await pdf.getPage\(i\);
    const text = extractPageText\(await page.getTextContent\(\)\);
    if \(text.includes\('216'\) && \(text.includes\('Incriminate'\) || text.includes\('Communication'\)\)\) {
      console.log\('=== PAGE', i, '==='\);
      console.log\(text.slice\(0, 600\)\);
      console.log\('---'\);
    }
  }
}
main\(\).catch\(e => console.error\(e\)\);
